// Set configuration
return [{
  json: {
    tenantId: $env.MS_TENANT_ID,
    clientId: $env.MS_CLIENT_ID,
    unusedDaysThreshold: 30
  }
}];

// Analyze license usage and identify issues
const skus = $node['Get SKUs'].json.value || [];
const users = $input.first().json.value || [];
const threshold = $node['Set Config'].json.unusedDaysThreshold;

const issues = [];
const skuMap = {};

// Build SKU lookup map
for (const sku of skus) {
  skuMap[sku.skuId] = {
    name: sku.skuPartNumber,
    total: sku.prepaidUnits.enabled,
    consumed: sku.consumedUnits,
    available: sku.prepaidUnits.enabled - sku.consumedUnits
  };
}

// Calculate days since sign-in
function daysAgo(dateString) {
  if (!dateString) return 9999;
  const then = new Date(dateString);
  const now = new Date();
  return Math.floor((now - then) / (1000 * 60 * 60 * 24));
}

// Check each licensed user
for (const user of users) {
  const lastSignIn = user.signInActivity?.lastSignInDateTime;
  const daysSinceSignIn = daysAgo(lastSignIn);

  // Unused license check
  if (daysSinceSignIn > threshold) {
    issues.push({
      type: 'UNUSED_LICENSE',
      severity: 'MEDIUM',
      userId: user.id,
      displayName: user.displayName,
      userPrincipalName: user.userPrincipalName,
      daysSinceSignIn: daysSinceSignIn,
      licenseCount: user.assignedLicenses.length,
      timestamp: new Date().toISOString()
    });
  }

  // Multiple licenses check
  if (user.assignedLicenses.length > 1) {
    issues.push({
      type: 'MULTIPLE_LICENSES',
      severity: 'LOW',
      userId: user.id,
      displayName: user.displayName,
      userPrincipalName: user.userPrincipalName,
      licenseCount: user.assignedLicenses.length,
      timestamp: new Date().toISOString()
    });
  }
}

// SKU utilization check
for (const [skuId, skuData] of Object.entries(skuMap)) {
  const utilizationPercent = (skuData.consumed / skuData.total) * 100;

  if (utilizationPercent < 50 && skuData.consumed > 0) {
    issues.push({
      type: 'LOW_SKU_UTILIZATION',
      severity: 'LOW',
      skuName: skuData.name,
      total: skuData.total,
      consumed: skuData.consumed,
      available: skuData.available,
      utilizationPercent: Math.round(utilizationPercent),
      timestamp: new Date().toISOString()
    });
  }
}

return [{
  json: {
    issues: issues,
    totalIssues: issues.length,
    unusedLicenses: issues.filter(i => i.type === 'UNUSED_LICENSE').length,
    totalLicensedUsers: users.length,
    totalSkus: skus.length,
    summary: {
      highSeverity: issues.filter(i => i.severity === 'HIGH').length,
      mediumSeverity: issues.filter(i => i.severity === 'MEDIUM').length,
      lowSeverity: issues.filter(i => i.severity === 'LOW').length
    }
  }
}];

// Format license audit report
const data = $input.first().json;
const issues = data.issues;

let message = `📊 *Daily License Audit Report*\n\n`;
message += `Total Issues: ${data.totalIssues}\n`;
message += `Licensed Users: ${data.totalLicensedUsers}\n`;
message += `SKUs: ${data.totalSkus}\n\n`;

if (data.totalIssues === 0) {
  message += `✅ No license issues detected`;
} else {
  message += `*Issue Breakdown*\n`;
  message += `• High: ${data.summary.highSeverity}\n`;
  message += `• Medium: ${data.summary.mediumSeverity}\n`;
  message += `• Low: ${data.summary.lowSeverity}\n\n`;

  // Group issues by type
  const unusedLicenses = issues.filter(i => i.type === 'UNUSED_LICENSE');
  const lowUtilization = issues.filter(i => i.type === 'LOW_SKU_UTILIZATION');

  if (unusedLicenses.length > 0) {
    message += `⚠️ *Unused Licenses (${unusedLicenses.length})*\n`;
    unusedLicenses.slice(0, 5).forEach(issue => {
      message += `• ${issue.displayName} - ${issue.daysSinceSignIn} days inactive\n`;
    });
    if (unusedLicenses.length > 5) {
      message += `... and ${unusedLicenses.length - 5} more\n`;
    }
    message += `\n`;
  }

  if (lowUtilization.length > 0) {
    message += `📉 *Low SKU Utilization (${lowUtilization.length})*\n`;
    lowUtilization.forEach(issue => {
      message += `• ${issue.skuName}: ${issue.utilizationPercent}% used (${issue.consumed}/${issue.total})\n`;
    });
  }
}

message += `\nTimestamp: ${new Date().toISOString()}`;

return [{
  json: {
    channel: '#license-alerts',
    text: message,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: '📊 License Audit Report',
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];
